import * as SecureStore from 'expo-secure-store';
import { createContext, ReactNode, useContext, useEffect, useState } from 'react';
import { Platform } from 'react-native';

import { checkUserLogin } from '@/api/api';

type AuthContextType = {
    user: any;
    isLoading: boolean;
    signIn: (token: string, userData: any) => Promise<void>;
    signOut: () => Promise<void>;
}

type AuthContextProps = {
    children: ReactNode;
}

const AuthContext = createContext<AuthContextType>({
    user: null,
    isLoading: true,
    signIn: async (token: string, userData: any) => {},
    signOut: async () => {},
});

export const useAuth = () => {
    return useContext(AuthContext);
}

export const AuthProvider = (props: AuthContextProps) => {
    const [user, setUser] = useState<any>(null);
    // 一打開就要檢查有沒有登入所以初始值是true
    const [isLoading, setIsLoading] = useState<boolean>(true);
    const getToken = async (key: string) => {
        if (Platform.OS === 'web') {
            return localStorage.getItem(key);
        }
        return await SecureStore.getItemAsync(key);
    };

    const setToken = async (key: string, value: string) => {
        if (Platform.OS === 'web') {
            localStorage.setItem(key, value);
        } else {
            await SecureStore.setItemAsync(key, value);
        }
    };

    const removeToken = async (key: string) => {
        if (Platform.OS === 'web') {
            localStorage.removeItem(key);
        } else {
            await SecureStore.deleteItemAsync(key);
        }
    };

    // 1. App 啟動時自動驗證 Token 的邏輯
    const checkAndVerifyToken = async () => {
        try {
            // 從加密儲存區拿出舊 Token
            const savedToken = await getToken('userToken');

            if (savedToken) {
                // 呼叫你的後端 API 驗證 Token 是否有效
                const result = await checkUserLogin(savedToken);

                if (result.isLogin) {
                    setUser(result); // Token 有效，設定使用者資料
                } else {
                    // Token 已過期或無效 -> 清除本地 Token
                    await removeToken('userToken');
                    setUser(null);
                }
            }
        } catch (error) {
            console.error('驗證 Token 失敗:', error);
            setUser(null);
        } finally {
            // 驗證完成，關閉全域 Loading 畫面
            setIsLoading(false);
        }
    };
    useEffect(() => {
        checkAndVerifyToken();
    }, []);

    // 2. 登入：將 Token 寫入 SecureStore，並更新 user 狀態
    const signIn = async (token: string, userData: any) => {
        await setToken('userToken', token);
        setUser(userData);
    };

    // 3. 登出：刪除 SecureStore 中的 Token，並清空 user 狀態
    const signOut = async () => {
        await removeToken('userToken');
        setUser(null);
    };

    return (
        <AuthContext.Provider value={{ user, isLoading, signIn, signOut }}>
            {props.children}
        </AuthContext.Provider>
    );
};
